using System.Diagnostics;
using System.Text.Json;
namespace EduForge.Api;
public sealed class PythonUnavailableException(string message) : Exception(message);
public sealed class PythonRunner {
 static readonly SemaphoreSlim Capacity=new(2);
 public async Task<string> Run(string code,string input,CancellationToken ct){await Capacity.WaitAsync(ct);var name="eduforge-run-"+Guid.NewGuid().ToString("N");try{using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(8));var start=new ProcessStartInfo("docker"){RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false,CreateNoWindow=true};foreach(var arg in new[]{"run","--rm","--pull=never","--name",name,"--network=none","--read-only","--memory=128m","--memory-swap=128m","--cpus=0.5","--pids-limit=32","--cap-drop=ALL","--security-opt=no-new-privileges","--user=65534:65534","--ulimit=nofile=64:64","-i","python:3.13-alpine","python","-I","-B","-c","import json,sys,io; d=json.loads(sys.stdin.readline()); sys.stdin=io.StringIO(d['input']); exec(compile(d['code'],'student.py','exec'),{'__name__':'__main__'})"})start.ArgumentList.Add(arg);using var process=Process.Start(start)??throw new InvalidOperationException();try{var output=ReadBounded(process.StandardOutput,timeout.Token);var error=ReadBounded(process.StandardError,timeout.Token);await process.StandardInput.WriteLineAsync(JsonSerializer.Serialize(new{code,input}).AsMemory(),timeout.Token);process.StandardInput.Close();await process.WaitForExitAsync(timeout.Token);var result=await output;var stderr=await error;if(process.ExitCode!=0){if(stderr.Contains("Unable to find image")||stderr.Contains("docker daemon")||stderr.Contains("pipe/docker")||stderr.Contains("failed to connect")||stderr.Contains("Cannot connect")||stderr.Contains("error during connect"))throw new PythonUnavailableException("Среда Python недоступна. Администратору нужно запустить Docker и подготовить образ.");throw new InvalidOperationException(stderr.Length>2000?stderr[..2000]:stderr);}return result;}finally{if(!process.HasExited)process.Kill(true);}}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new InvalidOperationException("Превышено время выполнения: 8 секунд.");}finally{try{var cleanup=new ProcessStartInfo("docker"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};cleanup.ArgumentList.Add("rm");cleanup.ArgumentList.Add("-f");cleanup.ArgumentList.Add(name);using var p=Process.Start(cleanup);if(p!=null){await p.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(3));}}catch{}Capacity.Release();}}
 static async Task<string> ReadBounded(StreamReader reader,CancellationToken ct){var chars=new char[16385];var count=0;while(count<chars.Length){var read=await reader.ReadAsync(chars.AsMemory(count),ct);if(read==0)return new string(chars,0,count);count+=read;}throw new InvalidOperationException("Вывод программы превышает 16 КБ.");}
}
